/// <summary>
/// This is a UI builder class for reserve event orders batch job.
/// </summary>
class METReserveEventOrdersUIBuilder  extends SysOperationAutomaticUIBuilder
{
    private METReserveEventOrdersContract contract;
    private DialogField                   orderTypeDialogField,
                                          salesIdDialogField,
                                          itemIdDialogField;

}

Method.Source:
/// <summary>
/// Overrides the method to add custom logic.
/// </summary>
public void postBuild()
{
    super();

    contract = this.dataContractObject() as METReserveEventOrdersContract;

    orderTypeDialogField = this.bindInfo().getDialogField(contract, methodStr(METReserveEventOrdersContract, parmOrderTypeId));
    itemIdDialogField    = this.bindInfo().getDialogField(contract, methodStr(METReserveEventOrdersContract, parmItemIdList));
    salesIdDialogField   = this.bindInfo().getDialogField(contract, methodStr(METReserveEventOrdersContract, parmSalesIdList));

    orderTypeDialogField.registerOverrideMethod(methodstr(FormStringControl, lookup),
                                                methodStr(METReserveEventOrdersUIBuilder, lookupOrderType),
                                                this);

    orderTypeDialogField.registerOverrideMethod(methodstr(FormStringControl, modified),
                                                methodStr(METReserveEventOrdersUIBuilder,modifiedOrderType),
                                                this);

    itemIdDialogField.lookupButton(FormLookupButton::Always);
    salesIdDialogField.lookupButton(FormLookupButton::Always);
}

/// <summary>
/// Overriden postRun method.
/// </summary>
public void postRun()
{
    this.constructItemIdLookup();
    this.constructSalesIdLookup();
    this.enableSalesAndItemIdFields();
}

/// <summary>
/// Constructs item Id multiselect lookup.
/// </summary>
private void constructItemIdLookup()
{
    Query		         query;
    QueryBuildDataSource qbds;

    query = new Query();
    qbds  = query.addDataSource(tablenum(InventTable));

    qbds.fields().addField(fieldNum(InventTable, ItemId));

    container selectedFields = [tableNum(InventTable), fieldNum(InventTable, ItemId)];

    SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), itemIdDialogField.control(), query, false, selectedFields);
}

/// <summary>
/// Constructs Sales ID multiselect lookup.
/// </summary>
private void constructSalesIdLookup()
{
    Query		         query;
    QueryBuildDataSource qbds;

    query = new Query();
    qbds  = query.addDataSource(tablenum(SalesTable));

    qbds.fields().addField(fieldNum(SalesTable, SalesId));

    container selectedFields = [tableNum(SalesTable), fieldNum(SalesTable, SalesId)];

    SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), salesIdDialogField.control(), query, false, selectedFields);
}

/// <summary>
///  Constructs lookup againt order type.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
private void lookupOrderType(FormStringControl _control)
{
    Query                query;
    QueryBuildDataSource qbds;
    SysTableLookup       sysTableLookup;

    query = new Query();
    qbds  = query.addDataSource(tableNum(METSalesOrderTypes));

    qbds.addRange(fieldNum(METSalesOrderTypes, IncSpecialOrders)).value(enum2Str(NoYes::Yes));

    sysTableLookup = SysTableLookup::newParameters(tableNum(METSalesOrderTypes), _control);

    sysTableLookup.addLookupField(fieldNum(METSalesOrderTypes,SalesOrderTypeID), true);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Triggers on form control modification.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
/// <returns>True, if modified; otherwise, false.</returns>
private boolean modifiedOrderType(FormStringControl _control)
{
    boolean ret = _control.modified();

    this.enableSalesAndItemIdFields();

    return ret;
}

/// <summary>
/// Enables/disables sales and item Id fields.
/// </summary>
private void enableSalesAndItemIdFields()
{
    boolean enable = (orderTypeDialogField.value() != '');

    salesIdDialogField.enabled(enable);
    itemIdDialogField.enabled(enable);

    if (!enable)
    {
        salesIdDialogField.value('');
        itemIdDialogField.value('');

        contract.parmSalesIdList(new List(Types::String));
        contract.parmItemIdList(new List(Types::String));
    }
}
